public void moveZeroes(int[] nums) {
    int[] buf = new int[nums.length];
    int idx = 0;
    for (int x : nums) {
        if (x != 0) {
            buf[idx++] = x;
        }
    }
    // remaining slots stay 0 by default
    System.arraycopy(buf, 0, nums, 0, nums.length);
}

public void moveZeroes(int[] nums) {
    int write = 0;
    for (int read = 0; read < nums.length; read++) {
        if (nums[read] != 0) {
            int tmp = nums[write];
            nums[write] = nums[read];
            nums[read] = tmp;
            write++;
        }
    }
}

